import { md5 } from "@allurereport/plugin-api";
const compareLegacyParameters = (first, second) => first.name.localeCompare(second.name) || first.value.localeCompare(second.value);
export const calculateLegacyHistoryId = ({ historyId, testCase, fullName, parameters = [], sourceMetadata, }) => {
    if (historyId) {
        return historyId;
    }
    const allureId = testCase?.allureId;
    const legacyTestCaseHash = sourceMetadata?.legacyTestCaseHash ??
        (allureId && allureId !== "-1"
            ? md5(`ALLURE_ID=${allureId}`)
            : testCase?.externalId
                ? md5(testCase.externalId)
                : fullName
                    ? md5(fullName)
                    : undefined);
    if (!legacyTestCaseHash) {
        return undefined;
    }
    const serializedParameters = [...parameters]
        .filter(({ excluded }) => !excluded)
        .sort(compareLegacyParameters)
        .map(({ name, value }) => `${name}:${value}`)
        .join(",");
    return `${legacyTestCaseHash}.${md5(serializedParameters)}`;
};
